import{_ as t,c as d,o as e,a4 as o}from"./chunks/framework.BYxathSa.js";const p=JSON.parse('{"title":"Q21：Cookie、localStorage、sessionStorage、IndexedDB 对比","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q21.md","filePath":"frontend/q21.md","lastUpdated":null}'),r={name:"frontend/q21.md"},a=o('<h1 id="q21-cookie、localstorage、sessionstorage、indexeddb-对比" tabindex="-1">Q21：Cookie、localStorage、sessionStorage、IndexedDB 对比 <a class="header-anchor" href="#q21-cookie、localstorage、sessionstorage、indexeddb-对比" aria-label="Permalink to &quot;Q21：Cookie、localStorage、sessionStorage、IndexedDB 对比&quot;">​</a></h1><table><thead><tr><th>特性</th><th>Cookie</th><th>localStorage</th><th>sessionStorage</th><th>IndexedDB</th></tr></thead><tbody><tr><td><strong>存储大小</strong></td><td>约 4KB</td><td>约 5MB</td><td>约 5MB</td><td>大容量（数百MB）</td></tr><tr><td><strong>生命周期</strong></td><td>可设过期时间；若不设，会话期有效</td><td>永久，除非手动清除</td><td>标签页关闭即清除</td><td>永久，需手动删除</td></tr><tr><td><strong>与服务器通信</strong></td><td>每次 HTTP 请求自动携带在 Cookie 头中</td><td>不自动发送</td><td>不自动发送</td><td>不自动发送</td></tr><tr><td><strong>作用域</strong></td><td>同源，可设 path</td><td>同源</td><td>同源且同一标签页</td><td>同源</td></tr><tr><td><strong>易用性</strong></td><td>操作麻烦，需封装</td><td>同步 API，简单</td><td>同步 API，简单</td><td>异步 API，强大，支持事务和索引</td></tr><tr><td><strong>应用场景</strong></td><td>维持登录状态、少量标识</td><td>持久化用户设置、主题</td><td>临时表单数据</td><td>离线应用、大量结构化数据</td></tr></tbody></table><p>注意：Cookie 设置 <code>HttpOnly</code> 可防 XSS 读取，<code>Secure</code> 只在 HTTPS 传输，<code>SameSite</code> 防 CSRF。</p>',3),s=[a];function n(c,i,l,_,g,h){return e(),d("div",null,s)}const f=t(r,[["render",n]]);export{p as __pageData,f as default};
